/* HEXA BATTLEGROUNDS setup — PART 94 OF 94. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-radio-16', 'radio', 'mission', 'Radio Frequency', 'logic', 2, array['transmission','boardroom','gate','terrace','any']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"141.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 1.5 MHz to the base.\nOdd channels then SUBTRACT 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 8."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1530","153"]}]'::jsonb, false, 3, 200, 'Base + channel × hop, then the odd-channel rule.', '141 + 8×1.5 = 153.0', null, 25, 'published'), ('mission-radio-17', 'radio', 'mission', 'Radio Frequency', 'logic', 2, array['transmission','boardroom','gate','terrace','any']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"154.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 0.5 MHz to the base.\nOdd channels then ADD 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 4."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1560","156"]}]'::jsonb, false, 3, 200, 'Base + channel × hop, then the odd-channel rule.', '154 + 4×0.5 = 156.0', null, 25, 'published'), ('mission-radio-18', 'radio', 'mission', 'Radio Frequency', 'logic', 2, array['transmission','boardroom','gate','terrace','any']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"134.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 0.5 MHz to the base.\nOdd channels then ADD 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 9."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1415"]}]'::jsonb, false, 3, 200, 'Base + channel × hop, then the odd-channel rule.', '134 + 9×0.5 + 3 = 141.5', null, 25, 'published'), ('mission-radio-19', 'radio', 'mission', 'Radio Frequency', 'logic', 2, array['transmission','boardroom','gate','terrace','any']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"176.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 0.5 MHz to the base.\nOdd channels then SUBTRACT 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 3."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1745"]}]'::jsonb, false, 3, 200, 'Base + channel × hop, then the odd-channel rule.', '176 + 3×0.5 − 3 = 174.5', null, 25, 'published'), ('battle-radio-40', 'radio', 'battle', 'Radio Frequency', 'logic', 2, array['duel_smg','duel_sniper']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"154.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 0.5 MHz to the base.\nOdd channels then ADD 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 4."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1560","156"]}]'::jsonb, false, 3, 90, 'Base + channel × hop, then the odd-channel rule.', '154 + 4×0.5 = 156.0', null, 25, 'published'), ('battle-radio-41', 'radio', 'battle', 'Radio Frequency', 'logic', 2, array['duel_smg','duel_sniper']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"129.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 2.5 MHz to the base.\nOdd channels then SUBTRACT 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 3."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1335"]}]'::jsonb, false, 3, 90, 'Base + channel × hop, then the odd-channel rule.', '129 + 3×2.5 − 3 = 133.5', null, 25, 'published'), ('battle-radio-42', 'radio', 'battle', 'Radio Frequency', 'logic', 2, array['duel_smg','duel_sniper']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"177.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 0.5 MHz to the base.\nOdd channels then SUBTRACT 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 6."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1800","180"]}]'::jsonb, false, 3, 90, 'Base + channel × hop, then the odd-channel rule.', '177 + 6×0.5 = 180.0', null, 25, 'published'), ('battle-radio-43', 'radio', 'battle', 'Radio Frequency', 'logic', 2, array['duel_smg','duel_sniper']::text[], 'Tune the squad radio to the rally channel. Answer with one decimal, like 141.5.', '{"scout":{"title":"Base frequency (painted on the tower)","body":"126.0 MHz","big":true},"decoder":{"title":"Hop rules","body":"Every channel adds 0.5 MHz to the base.\nOdd channels then ADD 3 MHz.","mono":true},"intel":{"title":"Today''s channel","body":"Rally on channel 1."}}'::jsonb, '[{"label":"Frequency (MHz)","accept":["1295"]}]'::jsonb, false, 3, 90, 'Base + channel × hop, then the odd-channel rule.', '126 + 1×0.5 + 3 = 129.5', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); create or replace function _lean_xy(j jsonb, p int default 4) returns jsonb language sql immutable set search_path = public as $$ select case when jsonb_typeof(j) = 'array' and jsonb_array_length(j) = 2 and jsonb_typeof(j -> 0) = 'number' and jsonb_typeof(j -> 1) = 'number' then jsonb_build_array(round((j ->> 0)::numeric, p), round((j ->> 1)::numeric, p)) else j end $$; create or replace function _lean_rivals(j jsonb) returns jsonb language sql immutable set search_path = public as $$ select coalesce(jsonb_agg( jsonb_strip_nulls(s) || case when jsonb_typeof(s -> 'pos') = 'array' then jsonb_build_object('pos', _lean_xy(s -> 'pos')) else '{}'::jsonb end || case when jsonb_typeof(s -> 'vel') = 'array' then jsonb_build_object('vel', _lean_xy(s -> 'vel', 6)) else '{}'::jsonb end || case when jsonb_typeof(s -> 'buggy') = 'array' then jsonb_build_object('buggy', _lean_xy(s -> 'buggy')) else '{}'::jsonb end order by o), '[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(j) = 'array' then j else '[]'::jsonb end) with ordinality as e(s, o) $$; do $$ begin if to_regprocedure('_arena_positions_v16(text)') is null then alter function arena_positions(text) rename to _arena_positions_v16; end if; end $$; revoke all on function _arena_positions_v16(text) from public; do $$ begin execute 'revoke all on function _arena_positions_v16(text) from anon'; exception when undefined_object then null; end $$; create or replace function arena_positions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; begin v := _arena_positions_v16(p_token); if jsonb_typeof(v -> 'squads') = 'array' then v := jsonb_set(v, '{squads}', _lean_rivals(v -> 'squads')); end if; return v; end $$; create or replace function player_state(p_token text, p_have jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; k text; hk text; h jsonb := '{}'::jsonb; r jsonb; mx float8; my float8; begin v := player_state(p_token); if jsonb_typeof(v) <> 'object' then return v; end if; if jsonb_typeof(v -> 'squads') = 'array' then v := jsonb_set(v, '{squads}', (select coalesce(jsonb_agg( case when jsonb_typeof(s -> 'pos') = 'array' then jsonb_set(s, '{pos}', _lean_xy(s -> 'pos')) else s end || case when jsonb_typeof(s -> 'vel') = 'array' then jsonb_build_object('vel', _lean_xy(s -> 'vel', 6)) else '{}'::jsonb end order by o), '[]'::jsonb) from jsonb_array_elements(v -> 'squads') with ordinality as e(s, o))); end if; if jsonb_typeof(v -> 'pickups') = 'array' then select (s -> 'pos' ->> 0)::float8, (s -> 'pos' ->> 1)::float8 into mx, my from jsonb_array_elements(coalesce(v -> 'squads', '[]'::jsonb)) s where s ->> 'id' = v -> 'team' ->> 'id' and jsonb_typeof(s -> 'pos') = 'array' limit 1; v := jsonb_set(v, '{pickups}', (select coalesce(jsonb_agg( x || jsonb_build_object('x', round((x ->> 'x')::numeric, 4), 'y', round((x ->> 'y')::numeric, 4)) order by o), '[]'::jsonb) from jsonb_array_elements(v -> 'pickups') with ordinality as e(x, o) where mx is null or ((x ->> 'x')::float8 - mx) ^ 2 + ((x ->> 'y')::float8 - my) ^ 2 <= 0.09)); end if; if v -> 'arena' ->> 'phase' = 'play' and coalesce(v -> 'me' ->> 'role', '') <> 'captain' then begin r := arena_positions(p_token); v := v || jsonb_build_object('rivals', r -> 'squads'); exception when others then null; end; end if; foreach k in array array['pickups', 'feed', 'story', 'leaderboard', 'roles', 'roster', 'alliances', 'bargains', 'codewords', 'comms', 'airdrops', 'inventory', 'event', 'results', 'last_result', 'mission', 'battle', 'online', 'squad', 'chat_last'] loop if v ? k then hk := left(md5(coalesce((v -> k)::text, 'null')), 10); h := h || jsonb_build_object(k, hk); if jsonb_typeof(p_have) = 'object' and p_have ->> k = hk then v := v - k; end if; end if; end loop; return v || jsonb_build_object('h', h); end $$; grant execute on function player_state(text, jsonb) to anon; grant execute on function arena_positions(text) to anon; revoke all on function _lean_xy(jsonb, int) from public; revoke all on function _lean_rivals(jsonb) from public; update mission_templates set clues = jsonb_set(clues, '{decoder,body}', to_jsonb((clues -> 'decoder' ->> 'body') || E'\nA total below zero is entered without the minus sign.')) where family = 'cricket' and position('below zero' in clues -> 'decoder' ->> 'body') = 0;
